"use client"

/**
 * File Dropzone (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/file-dropzone
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { NumberFlow } from "@/lib/notchset/number-flow"
import { useSound } from "@/lib/notchset/sound"

/*
 * File Dropzone: a 164px zone that comes alive under a drag (solid info border, 7% wash, the disc
 * fills and pulses, the arrow lifts, the zone grows 1.5%) and folds to a 76px strip once files land.
 * Each file is a tile whose outline is its progress; done greens the outline, fades it and pops a check
 * onto the type block; failed dashes it red, shakes, and offers Retry. Your upload code drives the
 * files; × removes a tile.
 */

type UploadStatus = "uploading" | "done" | "failed"

interface UploadFile {
  id: string
  name: string
  /** Bytes. */
  size: number
  /** 0–100. */
  progress: number
  status: UploadStatus
}

interface FileDropzoneProps extends Omit<React.ComponentPropsWithoutRef<"div">, "onDrop"> {
  files: readonly UploadFile[]
  onFiles: (files: File[]) => void
  onRetry: (id: string) => void
  onRemove: (id: string) => void
  accept?: string | undefined
  title?: string | undefined
  hint?: React.ReactNode | undefined
  /** Tints per extension, e.g. { JPG: "var(--chart-1)" }. */
  tints?: Record<string, string> | undefined
  sound?: boolean | undefined
}

const fmt = (b: number) => (b > 1048576 ? `${(b / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(b / 1024))} KB`)
const ext = (n: string) => (n.split(".").pop() ?? "file").toUpperCase().slice(0, 4)

const FileDropzone = React.forwardRef<HTMLDivElement, FileDropzoneProps>(function FileDropzone(
  { files, onFiles, onRetry, onRemove, accept, title = "Drop files here", hint = "or click to browse", tints = {}, sound = true, className, ...props },
  ref
) {
  const { sfx } = useSound(sound)
  const input = React.useRef<HTMLInputElement>(null)
  const [over, setOver] = React.useState(false)
  const [leaving, setLeaving] = React.useState<string[]>([])
  const prev = React.useRef(new Map<string, UploadStatus>())
  React.useEffect(() => {
    let k = 0
    for (const f of files) {
      const was = prev.current.get(f.id)
      if (was && was !== f.status) {
        if (f.status === "done") window.setTimeout(() => sfx.ding(2), k++ * 90)
        else if (f.status === "failed") sfx.buzz()
      }
      prev.current.set(f.id, f.status)
    }
  }, [files, sfx])
  React.useEffect(() => {
    if (!leaving.length) return
    const t = window.setTimeout(() => {
      leaving.forEach(onRemove)
      setLeaving([])
    }, 380)
    return () => window.clearTimeout(t)
  }, [leaving, onRemove])

  const has = files.length > 0
  const take = (list: FileList | null) => {
    const arr = Array.from(list ?? [])
    setOver(false)
    if (!arr.length) return
    sfx.pop()
    onFiles(arr)
  }

  return (
    <div ref={ref} data-slot="file-dropzone" data-notchset="" className={cn("flex w-full max-w-[440px] flex-col gap-3", className)} {...props}>
      <input ref={input} type="file" multiple accept={accept} className="hidden" onChange={(e) => {
        take(e.target.files)
        e.target.value = ""
      }} />
      <div
        role="button"
        tabIndex={0}
        aria-label={`${title}. ${typeof hint === "string" ? hint : "Upload files"}`}
        onClick={() => input.current?.click()}
        onKeyDown={(e) => {
          if (e.key !== "Enter" && e.key !== " ") return
          e.preventDefault()
          input.current?.click()
        }}
        onDragOver={(e) => {
          e.preventDefault()
          if (!over) {
            setOver(true)
            sfx.open()
          }
        }}
        onDragLeave={() => setOver(false)}
        onDrop={(e) => {
          e.preventDefault()
          take(e.dataTransfer.files)
        }}
        className={cn(
          "flex cursor-pointer flex-col items-center justify-center overflow-hidden rounded-[22px] border-[1.5px] outline-none [transition:height_.55s_cubic-bezier(.2,1.2,.3,1),gap_.45s,border-color_var(--ns-time-color),background-color_var(--ns-time-color),scale_.3s_cubic-bezier(.2,1.4,.3,1)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] motion-reduce:transition-none",
          over ? "scale-[1.015] border-solid border-[var(--info,var(--chart-1))] bg-[color-mix(in_oklab,var(--info,var(--chart-1))_7%,var(--background))]" : "border-dashed border-[color-mix(in_oklab,var(--foreground)_22%,var(--border))] bg-[var(--background)]",
          has ? "h-[76px] gap-1.5" : "h-[164px] gap-3"
        )}
      >
        <span className={cn("relative grid shrink-0 place-items-center rounded-full [transition:width_.45s_var(--ns-ease-reshape),height_.45s_var(--ns-ease-reshape),background-color_var(--ns-time-color),color_var(--ns-time-color)]", over ? "bg-[var(--info,var(--chart-1))] text-white" : "bg-[var(--muted)] text-[var(--foreground)]", has ? "size-[30px]" : "size-11")}>
          {over && <span aria-hidden="true" className="absolute -inset-1.5 animate-[ns-halo-ring_1.4s_ease-out_infinite] rounded-full border-2 border-[var(--info,var(--chart-1))] opacity-0 motion-reduce:hidden" />}
          <svg viewBox="0 0 24 24" aria-hidden="true" className="size-4 [transition:translate_.45s_var(--ns-ease-pop)]" style={{ translate: over ? "0 -3px" : "0 0" }} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="m5 12 7-7 7 7" />
            <path d="M12 19V5" />
          </svg>
        </span>
        <span className="flex flex-col items-center gap-[3px]">
          <span className="text-[length:var(--ns-type-copy)] font-semibold whitespace-nowrap">{over ? "Let go to upload" : title}</span>
          <span className="overflow-hidden text-[12.5px] whitespace-nowrap text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))] [transition:max-height_.4s,opacity_.25s]" style={{ maxHeight: has ? 0 : 20, opacity: has ? 0 : 1 }}>
            {hint}
          </span>
        </span>
      </div>
      {has && (
        <ul className="m-0 grid list-none grid-cols-3 gap-2.5 p-0 max-[400px]:grid-cols-2">
          {files.map((f) => {
            const ok = f.status === "done"
            const fail = f.status === "failed"
            const x = ext(f.name)
            const tint = tints[x] ?? "var(--chart-3)"
            const gone = leaving.includes(f.id)
            return (
              <li
                key={`${f.id}-${fail ? "f" : "a"}`}
                className={cn("relative flex min-h-[124px] flex-col gap-2 rounded-[16px] p-3 [transition:opacity_.25s,scale_.4s_var(--ns-ease-reshape),background-color_.3s]", fail ? "animate-[ns-shake_.42s] bg-[color-mix(in_oklab,var(--destructive)_6%,var(--background))]" : "animate-[ns-drop-in-face_.45s_var(--ns-ease-pop)_both] bg-[var(--background)]", "motion-reduce:animate-none")}
                style={{ opacity: gone ? 0 : 1, scale: gone ? ".6" : "1" }}
              >
                <svg aria-hidden="true" className="pointer-events-none absolute inset-0 size-full overflow-visible">
                  <rect x=".5" y=".5" rx="15.5" fill="none" stroke="var(--border)" strokeWidth="1" style={{ width: "calc(100% - 1px)", height: "calc(100% - 1px)" }} />
                  <rect
                    x="1"
                    y="1"
                    rx="15"
                    fill="none"
                    strokeWidth="2"
                    pathLength={1}
                    strokeDasharray={fail ? ".03 .02" : "1"}
                    strokeDashoffset={fail ? 0 : 1 - f.progress / 100}
                    className="[transition:stroke-dashoffset_.15s_linear,stroke_.3s,opacity_.5s_.5s]"
                    style={{ width: "calc(100% - 2px)", height: "calc(100% - 2px)", stroke: fail ? "var(--destructive)" : ok ? "var(--success,var(--chart-3))" : "var(--info,var(--chart-1))", opacity: ok ? 0 : 1 }}
                  />
                </svg>
                <div className="relative flex items-start justify-between">
                  <span className="relative grid size-10 place-items-center rounded-[11px] font-mono text-[9.5px] font-bold" style={{ background: `color-mix(in oklab, ${tint} 16%, transparent)`, color: `color-mix(in oklab, ${tint} 75%, var(--foreground))` }}>
                    {x}
                    <span aria-hidden="true" className="absolute -end-[5px] -bottom-[5px] grid size-[18px] place-items-center rounded-full bg-[var(--success,var(--chart-3))] text-[var(--success-foreground,#fff)] shadow-[0_0_0_2px_var(--background)] [transition:opacity_.2s,scale_.4s_var(--ns-ease-rebound)]" style={{ opacity: ok ? 1 : 0, scale: ok ? "1" : ".4" }}>
                      <svg viewBox="0 0 24 24" className="size-2.5" fill="none" stroke="currentColor" strokeWidth="3.2" strokeLinecap="round" strokeLinejoin="round">
                        <path d="M20 6 9 17l-5-5" />
                      </svg>
                    </span>
                  </span>
                  <button
                    type="button"
                    aria-label={`Remove ${f.name}`}
                    onClick={() => {
                      sfx.drop()
                      setLeaving((l) => [...l, f.id])
                    }}
                    className="-me-1 -mt-1 grid size-[26px] cursor-pointer place-items-center rounded-full text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))] outline-none hover:bg-[var(--accent)] hover:text-[var(--foreground)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))]"
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true" className="size-3" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M18 6 6 18" />
                      <path d="m6 6 12 12" />
                    </svg>
                  </button>
                </div>
                <span className="relative mt-auto flex min-w-0 flex-col gap-0.5">
                  <span className="truncate text-[12.5px] font-semibold">{f.name}</span>
                  <span
                    aria-live="polite"
                    className={cn("flex items-center gap-1 font-mono text-[10.5px] whitespace-nowrap", ok && "text-[color-mix(in_oklab,var(--success,var(--chart-3))_75%,var(--foreground))]", fail && "text-[var(--destructive)]", !ok && !fail && "text-[color:var(--ns-ink-support,color-mix(in_oklab,var(--muted-foreground)_85%,var(--foreground)))]")}
                  >
                    {f.status === "uploading" && (
                      <span className="inline-flex">
                        <NumberFlow value={`${Math.round(f.progress)}%`} />
                      </span>
                    )}
                    {ok ? `${fmt(f.size)} · done` : fail ? `Dropped at ${Math.round(f.progress)}%` : ` · ${fmt(f.size)}`}
                  </span>
                  {fail && (
                    <button
                      type="button"
                      onClick={() => {
                        sfx.tone(600, 0.1, "sine", 0.035, 0, 900)
                        onRetry(f.id)
                      }}
                      className="mt-0.5 flex h-[26px] animate-[ns-chip_.4s_var(--ns-ease-pop)_both] cursor-pointer items-center justify-center gap-1.5 rounded-full bg-[var(--destructive)] text-[length:var(--ns-type-note)] font-semibold text-white outline-none focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] active:scale-95"
                    >
                      Retry
                    </button>
                  )}
                </span>
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
})

export { FileDropzone, type FileDropzoneProps, type UploadFile, type UploadStatus }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * NumberFlow: the fluid number every changing figure renders through (countdowns, times, counts, totals).
 * Each digit is its own 0–9 column that springs to the new digit with a slight motion blur; digits that
 * appear or disappear animate their width, so the text never jumps. Other characters (":", ",", " ")
 * swap in place. Screen readers get the plain value.
 */

const H = 1.15 // em, one digit row

function Digit({ d, enter, tight }: { d: number; enter: boolean; tight?: boolean | undefined }) {
  // Each change flips between two identical blur keyframes, so the blur restarts every time.
  const [seen, setSeen] = React.useState(d)
  const [flips, setFlips] = React.useState(0)
  if (seen !== d) {
    setSeen(d)
    setFlips((n) => n + 1)
  }
  return (
    <span
      aria-hidden="true"
      className={cn(
        "relative inline-block [clip-path:inset(0_-0.15em)]",
        // Tight digits are narrower than their glyphs: they clip only up and down (the clip-path bounds the sides), so a 1 isn't cut.
        tight ? "[overflow-x:visible] [overflow-y:clip] transition-[width] duration-[.55s] ease-[var(--ns-ease-settle)] motion-reduce:transition-none" : "w-[1ch] overflow-hidden",
        enter && "animate-[ns-num-in_.55s_var(--ns-ease-settle)_both] motion-reduce:animate-none"
      )}
      // Tight digits: a 1 is narrower than the rest, as in a headline price.
      style={{ height: `${H}em`, lineHeight: `${H}em`, width: tight ? (d === 1 ? "0.43em" : "0.58em") : undefined }}
    >
      <span
        className={cn(
          "flex flex-col",
          // Tight: each glyph keeps a box as wide as itself, centred in the narrower slot.
          tight && "items-center",
          "[transition:transform_.85s_var(--ns-ease-settle),scale_.85s_var(--ns-ease-settle),translate_.85s_var(--ns-ease-settle),rotate_.85s_var(--ns-ease-settle)] motion-reduce:transition-none",
          flips > 0 && (flips % 2 ? "animate-[ns-num-blur_.45s_ease-out]" : "animate-[ns-num-blur-b_.45s_ease-out]")
        )}
        style={{ transform: `translateY(${-d * H}em)` }}
      >
        {Array.from({ length: 10 }, (_, i) => (
          <span key={i} className={cn("block text-center", tight && "w-[0.76em] shrink-0")} style={{ height: `${H}em` }}>
            {i}
          </span>
        ))}
      </span>
    </span>
  )
}

interface NumberFlowProps extends Omit<React.ComponentPropsWithoutRef<"span">, "children"> {
  /** The value as it should read, e.g. 42, "09:30" or "1,204". */
  value: string | number
  /** Proportional digit widths (a 1 is 0.43em, the rest 0.58em), for large headline figures. */
  tight?: boolean | undefined
}

const NumberFlow = React.forwardRef<HTMLSpanElement, NumberFlowProps>(function NumberFlow({ value, tight, className, ...props }, ref) {
  const text = String(value)
  const chars = Array.from(text)
  // Positions are counted from the right, so the ones digit stays the ones digit when the length changes.
  const [initialLength] = React.useState(chars.length)
  const [prev, setPrev] = React.useState(text)
  const [leaving, setLeaving] = React.useState<{ id: string; ch: string }[]>([])
  if (prev !== text) {
    const old = Array.from(prev)
    if (old.length > chars.length) {
      const gone = old.slice(0, old.length - chars.length).filter((ch) => ch >= "0" && ch <= "9")
      setLeaving((l) => [...l, ...gone.map((ch, i) => ({ id: `${prev}>${text}:${i}`, ch }))].slice(-4))
    }
    setPrev(text)
  }

  return (
    <span ref={ref} data-slot="number-flow" className={cn("inline-flex whitespace-nowrap tabular-nums", className)} {...props}>
      <span className="sr-only">{text}</span>
      {leaving.map((g) => (
        <span
          key={`out-${g.id}`}
          aria-hidden="true"
          className="inline-block w-0 animate-[ns-num-out_.45s_var(--ns-ease-settle)_both] overflow-hidden text-center"
          style={{ height: `${H}em`, lineHeight: `${H}em` }}
          onAnimationEnd={() => setLeaving((l) => l.filter((x) => x.id !== g.id))}
        >
          {g.ch}
        </span>
      ))}
      {chars.map((ch, i) => {
        const pos = chars.length - i
        return ch >= "0" && ch <= "9" ? (
          <Digit key={`d${pos}`} d={Number(ch)} enter={pos > initialLength} tight={tight} />
        ) : (
          <span key={`s${pos}`} aria-hidden="true" className="inline-block whitespace-pre" style={{ height: `${H}em`, lineHeight: `${H}em` }}>
            {ch}
          </span>
        )
      })}
    </span>
  )
})

export { NumberFlow, type NumberFlowProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * The shared parts: the rolling label every state change goes through, the check that draws
 * itself, the spinner and the live dot, and a timeline that schedules a component's steps and clears
 * them when it unmounts. Every class string is a plain literal (the shadcn CLI only rewrites those for
 * apps with tailwind.prefix). Keyframes (ns-*) live in the foundation CSS.
 *
 * Easing vocabulary (the design's names): press var(--ns-ease-press) for scale on press; roll
 * var(--ns-ease-reshape) for label rolls, menus and width morphs; pop var(--ns-ease-pop) for
 * icon swaps and checks landing; draw cubic-bezier(.6,0,.2,1) for strokes and sweeps; exit
 * cubic-bezier(.6,0,.9,.5) for things leaving.
 */

/** Runs on the client before paint, and as an effect on the server (React 18 warns about layout effects there). */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/** Points one ref (callback or object) at `node`. */
function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") ref(node)
  else if (ref) (ref as React.MutableRefObject<T | null>).current = node
}

/** Sets every ref passed (callback or object), so a component can keep its own ref and forward the caller's. */
function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  const latest = React.useRef(refs)
  useIsomorphicLayoutEffect(() => {
    latest.current = refs
  })
  return React.useCallback((node: T | null) => {
    for (const ref of latest.current) assignRef(ref, node)
  }, [])
}

/** Schedules a component's steps; every pending step is cleared on clear() and on unmount. */
function useTimeline() {
  const timers = React.useRef<Set<ReturnType<typeof setTimeout>>>(new Set())
  React.useEffect(() => {
    const set = timers.current
    return () => {
      for (const t of set) clearTimeout(t)
      set.clear()
    }
  }, [])
  return React.useMemo(
    () => ({
      after(ms: number, fn: () => void) {
        const t = setTimeout(() => {
          timers.current.delete(t)
          fn()
        }, ms)
        timers.current.add(t)
        return t
      },
      clear() {
        for (const t of timers.current) clearTimeout(t)
        timers.current.clear()
      },
    }),
    []
  )
}

/** Resolves after `ms` (a minimum time a state shows, so a fast promise still reads). */
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/**
 * A fixed-height window over a stack of rows; row `index` shows, the others roll past (.5s roll). Only
 * the showing row is in the accessibility tree, so the button's name is always the current label.
 */
function RollingLabel({ rows, index, size = "default", align = "center", fit = false, rowHeight, className }: { rows: readonly React.ReactNode[]; index: number; size?: "default" | "sm" | undefined; align?: "center" | "start" | undefined; /** Rows as wide as their own text (inside a window sized to the active row). */ fit?: boolean | undefined; /** A row height in px, for titles (overrides size). */ rowHeight?: number | undefined; className?: string | undefined }) {
  const height = rowHeight ?? (size === "sm" ? 18 : 20)
  return (
    <span data-slot="rolling-label" className={cn("relative block overflow-hidden", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), className)} style={rowHeight ? { height: rowHeight } : undefined}>
      <span
        className={cn("flex flex-col transition-transform duration-500 ease-[var(--ns-ease-reshape)] motion-reduce:transition-none", fit && (align === "center" ? "items-center" : "items-start"))}
        style={{ transform: `translateY(${-index * height}px)` }}
      >
        {rows.map((row, i) => (
          <span
            key={i}
            aria-hidden={i === index ? undefined : true}
            className={cn("flex shrink-0 items-center gap-2 whitespace-nowrap", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), align === "center" ? "justify-center" : "justify-start", fit && "w-max")}
            style={rowHeight ? { height: rowHeight, lineHeight: `${rowHeight}px` } : undefined}
          >
            {row}
          </span>
        ))}
      </span>
    </span>
  )
}

/** The check that draws itself in (.45s draw after .15s) when `shown`. */
function DrawCheck({ shown, className }: { shown: boolean; className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-4 shrink-0", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path
        d="M20 6 9 17l-5-5"
        className="[stroke-dasharray:24] transition-[stroke-dashoffset] delay-150 duration-[450ms] ease-[cubic-bezier(.6,0,.2,1)] motion-reduce:transition-none"
        style={{ strokeDashoffset: shown ? 0 : 24 }}
      />
    </svg>
  )
}

/** The 14px spinner: an arc turning every .7s. */
function Spinner({ className }: { className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 shrink-0 animate-[ns-spin_.7s_linear_infinite]", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <circle cx="12" cy="12" r="9" className="[stroke-dasharray:20_40]" />
    </svg>
  )
}

/** A 7px dot with a ring that keeps blooming out of it (live). */
function LiveDot({ className }: { className?: string | undefined }) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex size-[7px] shrink-0", className)}>
      <span className="absolute inset-0 animate-[ns-live_1.2s_ease-out_infinite] rounded-full bg-current" />
      <span className="relative size-full rounded-full bg-current" />
    </span>
  )
}

/**
 * Where overlays (menus, tooltips) portal to. Unset, they portal to document.body, where your
 * :root theme applies. Set it when the theme lives on an element instead of :root:
 *   <PortalContext.Provider value={element}>…</PortalContext.Provider>
 */
const PortalContext = React.createContext<HTMLElement | null>(null)

/** The container for an overlay's Portal: the provided element, else undefined (document.body). */
function usePortal() {
  return React.useContext(PortalContext) ?? undefined
}

/**
 * Writes text to the clipboard and resolves true only when it landed (falls back to a hidden textarea
 * where the async API is missing or blocked). Show "Copied" only on true.
 */
async function copyText(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text)
      return true
    }
  } catch {
    // Blocked (permissions, an insecure origin): try the fallback below.
  }
  try {
    const area = document.createElement("textarea")
    area.value = text
    area.setAttribute("readonly", "")
    area.style.position = "fixed"
    area.style.opacity = "0"
    document.body.appendChild(area)
    area.select()
    const copied = document.execCommand("copy")
    area.remove()
    return copied
  } catch {
    return false
  }
}

/**
 * A callback ref that sets the inert attribute (React 18 has no inert prop): hidden panes and folded
 * sections stay out of the tab order and the accessibility tree.
 */
function inertRef(on: boolean) {
  return (node: HTMLElement | null) => {
    node?.toggleAttribute("inert", on)
  }
}

/** True while an IME is composing: key handlers that commit text ignore those keys. */
function composing(event: React.KeyboardEvent) {
  return event.nativeEvent.isComposing || event.keyCode === 229
}

/** True when focus is in a text field (single-key shortcuts stay out of the way). */
function typingInField() {
  const el = document.activeElement as HTMLElement | null
  return Boolean(el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable))
}

/** A label's text for the live region: the label itself when it is text, else `fallback`. */
function spoken(label: React.ReactNode, fallback: string) {
  return typeof label === "string" || typeof label === "number" ? String(label) : fallback
}

/** A polite live region that says `message` whenever it changes (label rolls, outcomes). */
function Announcer({ message }: { message: string }) {
  return (
    <span aria-live="polite" className="sr-only">
      {message}
    </span>
  )
}

const REDUCED = "(prefers-reduced-motion: reduce)"

/**
 * Whether motion should be calm right now: the OS asks for reduced motion, or `el` sits under
 * data-motion="off". For event handlers and effects (it reads the DOM).
 */
function prefersCalm(el?: Element | null) {
  if (typeof window === "undefined") return false
  return Boolean(window.matchMedia?.(REDUCED).matches || el?.closest('[data-motion="off"]'))
}

/**
 * Whether `el` sits in an RTL scope: the nearest `dir`, as Tailwind's `rtl:` styles read it, so a
 * dir="rtl" panel inside an LTR page (or the reverse) maps pointer and arrow keys the way it's drawn.
 */
function isRtl(el?: Element | null) {
  if (typeof window === "undefined") return false
  if (!el) return document.dir === "rtl"
  try {
    return el.matches(":dir(rtl)")
  } catch {
    return el.closest("[dir]")?.getAttribute("dir") === "rtl"
  }
}

/**
 * The one failure contract every action callback follows: it failed if it threw (handled by the caller),
 * or resolved `false`, a failed Response (`!res.ok`) or an object with an `error` (any value).
 */
function isFailedResult(result: unknown): boolean {
  if (result === false) return true
  if (typeof Response !== "undefined" && result instanceof Response) return !result.ok
  return typeof result === "object" && result !== null && "error" in result && (result as { error: unknown }).error != null
}

/** The message a failure carries, if it has one: a thrown Error's, or `{ error: "text" }`'s / `{ error: { message } }`'s. */
function failureMessage(reason: unknown): string {
  if (reason instanceof Error) return reason.message
  if (typeof reason === "object" && reason !== null && "error" in reason) {
    const e = (reason as { error: unknown }).error
    if (typeof e === "string") return e
    if (typeof e === "object" && e !== null && typeof (e as { message?: unknown }).message === "string") return (e as { message: string }).message
  }
  return ""
}

const noSubscribe = () => () => {}
/**
 * Now, on the client only: null on the server and during hydration (so both render the same in every
 * time zone), then the visitor's clock. For anything that shows "today" without a `today` prop.
 */
function useClientNow(): Date | null {
  const mounted = React.useSyncExternalStore(noSubscribe, () => true, () => false)
  const [now] = React.useState(() => (typeof window === "undefined" ? null : new Date()))
  return mounted ? (now ?? new Date()) : null
}

const subscribeReduced = (onChange: () => void) => {
  const mq = window.matchMedia?.(REDUCED)
  mq?.addEventListener("change", onChange)
  return () => mq?.removeEventListener("change", onChange)
}

/**
 * The OS reduced-motion preference for render, following changes. False on the server and during
 * hydration (so both render the same), then the real value.
 */
function useCalm() {
  return React.useSyncExternalStore(subscribeReduced, () => Boolean(window.matchMedia?.(REDUCED).matches), () => false)
}

